<script setup lang="ts">
import {computed,ref} from 'vue'
import {CheckCircle2,AlertTriangle,Clock3,LoaderCircle,ChevronRight,Minus} from 'lucide-vue-next'
import type {Row} from '../lib'
import {buildPaymentJourney} from '../paymentJourney'
import PaymentTraceEvents from './PaymentTraceEvents.vue'
const props=defineProps<{events:Row[];links?:Row[];order:Row;payment?:Row;billing?:Row;checkout?:Row}>()
const journey=computed(()=>buildPaymentJourney(props))
const logFilter=ref('all')
const logs=computed(()=>props.events.filter(e=>logFilter.value==='all'||logFilter.value==='attention'&&(['failed','review'].includes(e.state)||e.http_status>=400&&e.code!=='subscription_absent')||logFilter.value==='network'&&e.phase==='network'))
const stageLabels:Record<string,string>={completed:'已完成',running:'进行中',waiting:'等待',failed:'未完成',review:'需处理',skipped:'已跳过'}
</script>
<template>
<section class="payment-journey" aria-label="办理结果与阶段进度">
 <div class="journey-heading"><div><span class="eyebrow">ORDER RESULT</span><h3>{{journey.result}}</h3></div><span class="journey-duration">全程耗时 · {{journey.total}}</span></div>
 <dl class="journey-summary"><div v-for="item in journey.summary" :key="item.label"><dt>{{item.label}}</dt><dd>{{item.value}}</dd></div></dl>
 <p v-if="journey.attention" class="journey-attention"><AlertTriangle :size="16"/>需要处理：{{journey.attention}}。具体原因与建议见下方展开内容。</p>
 <div class="journey-section-heading"><h4>办理阶段</h4><span>同一阶段合并展示 · {{journey.rounds}} 轮结账</span></div>
 <ol class="journey-stages">
  <li v-for="stage in journey.stages" :key="stage.id" :data-stage="stage.id" :class="stage.state">
   <span class="journey-icon"><CheckCircle2 v-if="stage.state==='completed'" :size="18"/><AlertTriangle v-else-if="['failed','review'].includes(stage.state)" :size="18"/><LoaderCircle v-else-if="stage.state==='running'" :size="18"/><Minus v-else-if="stage.state==='skipped'" :size="18"/><Clock3 v-else :size="18"/></span>
   <details class="journey-stage" :open="['failed','review'].includes(stage.state)">
    <summary><span class="journey-stage-title"><b>{{stage.title}}</b><span class="journey-stage-result">{{stage.result}}</span></span><span class="journey-stage-meta"><span class="journey-state">{{stageLabels[stage.state]}}</span><small v-if="stage.duration!=='未记录'">{{stage.duration}}</small><ChevronRight class="journey-chevron" :size="16"/></span></summary>
    <div class="journey-stage-body"><dl><div v-for="fact in stage.facts" :key="fact.label"><dt>{{fact.label}}</dt><dd>{{fact.value}}</dd></div></dl><p v-if="stage.next" class="journey-next">{{stage.next}}</p><p v-if="!stage.events.length" class="journey-note">此阶段没有保留独立过程日志；结果以订单已保存的业务状态为准。</p></div>
   </details>
  </li>
 </ol>
 <details class="journey-technical"><summary>技术日志 <span>{{events.length}} 条原始记录 · 按需查看</span><ChevronRight :size="15"/></summary><div class="journey-log-toolbar"><label>筛选记录<select v-model="logFilter"><option value="all">全部记录</option><option value="attention">异常与待核实</option><option value="network">网络检查</option></select></label><small>接口返回、过程完成和业务成功分别保留；日志条数不代表付款或取消次数。</small></div><PaymentTraceEvents :events="logs"/></details>
</section>
</template>
